import{z as l,x as i,o as s,c as d,q as r,j as t,D as B,d as a,s as A,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"自旋锁","description":"","frontmatter":{"title":"自旋锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spinlock.md","filePath":"cs/spinlock.md","lastUpdated":1791413859000}'),p={name:"cs/spinlock.md"};function c(C,E,D,m,_,S){const o=i("Mermaid");return s(),d("div",null,[E[2]||(E[2]=r('<h1 id="自旋锁" tabindex="-1">自旋锁 <a class="header-anchor" href="#自旋锁" aria-label="Permalink to &quot;自旋锁&quot;">​</a></h1><div class="epigraph"><p>自旋锁在拿不到时原地忙等；持有期间不能睡眠，临界区必须短，否则它把 CPU 烧成等待器。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/lock-irq">上一课</a>给出互斥要用原子能力，并分清：IRQ 上下文只能忙等，同核还要关中断。缺口是把 <strong>spinlock</strong> 收成对象：锁字 + 获取时循环 RMW + 释放时写 0 并带 release 语义。本课钉何时能用、为何不能睡，不把 MCS 队列锁写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>睡眠锁在拿不到时<a href="/cs/context-switch">上下文切换</a>，但 ISR 与软中断不能调度。共享「线程与硬 IRQ」的队列必须自旋。单核上若不关 IRQ，持锁线程被同核 ISR 抢到同一把锁会自死等。多核上关本地 IRQ 挡不住他核，仍要自旋。缺口不是再讲 RMW 指令，而是这把<strong>短临界区锁</strong>的纪律。</p><p><span class="marginnote">持自旋锁时开抢占会让持有者被迁走，等待者在别的核上空转。因此获取路径关抢占；释放时再开。</span></p><p><span class="marginnote">术语翻译：<code>test_and_set</code>（TAS）就是一条指令内原子地「读出锁字旧值 + 写入 1」——因为读和改之间插不进别的核，所以多个抢锁者里只会有一个读到 0 而成功。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>spin_lock</code>：关抢占，必要时关本地 IRQ（<code>spin_lock_irqsave</code>），然后 <code>while (test_and_set)</code>；有的实现先读后 TAS 以减轻乒乓。<code>spin_unlock</code>：store-release 清锁，恢复 IRQ 与抢占。临界区只碰已经在内存里的结构，不调可能睡眠的分配、不 <code>copy_from_user</code>。</p>',9)),(s(),t(n,null,{default:B(()=>[A(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACQ%5B%22%E5%85%B3%E6%8A%A2%E5%8D%A0%E5%B9%B6%20TAS%20%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20CS%5B%22%E6%9E%81%E7%9F%AD%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%0A%20%20CS%20--%3E%20REL%5B%22release%20%E6%B8%85%E9%94%81%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"调试用的锁依赖检测记住获取顺序，那是死锁课；本课只要求一把锁的正确用法。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("自旋把等待变成 CPU 时间，换来不睡眠、可在 IRQ 用。临界区一长，"),e("a",{href:"/cs/scheduling-metrics"},"调度指标"),a(" 的响应与实时 WCET 一起坏掉，也会加重反转：高优先级在自旋，低优先级持锁却跑不完。PI 对纯自旋支持差，因为等待者不睡，调度器看不见。")],-1)),E[6]||(E[6]=e("p",null,"简单 TAS 锁所有等待者打同一 cache 行；核多时要排队锁，下一课 MCS。",-1)),(s(),t(n,null,{default:B(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%BA%BF%E7%A8%8B%20A%20%E6%8C%81%E9%94%81%EF%BC%8C%E6%9C%AA%E5%85%B3%E6%9C%AC%E5%9C%B0%20IRQ%22%5D%20--%3E%20P%5B%22%E5%90%8C%E6%A0%B8%E6%97%B6%E9%92%9F%E4%B8%AD%E6%96%AD%E6%8A%A2%E5%8D%A0%20A%22%5D%0A%20%20P%20--%3E%20I%5B%22ISR%20%E6%83%B3%E6%8B%BF%E5%90%8C%E4%B8%80%E6%8A%8A%E9%94%81%22%5D%0A%20%20I%20--%3E%20SP%5B%22ISR%20%E8%87%AA%E6%97%8B%E7%AD%89%E9%94%81%E9%87%8A%E6%94%BE%22%5D%0A%20%20SP%20--%3E%20W%7B%22A%20%E4%BD%95%E6%97%B6%E8%83%BD%E7%BB%A7%E7%BB%AD%E8%B7%91%EF%BC%9F%22%7D%0A%20%20W%20--%3E%7C%22%E5%90%8C%E6%A0%B8%E4%B8%94%E6%8A%A2%E5%8D%A0%E6%9C%AA%E5%85%B3%22%7C%20D%5B%22A%20%E8%A2%AB%E5%8E%8B%E5%9C%A8%20ISR%20%E4%B8%8B%E9%9D%A2%E6%B0%B8%E4%B8%8D%E8%BF%90%E8%A1%8C%3Cbr%2F%3E%E6%AD%BB%E7%AD%89%EF%BC%8C%E7%B3%BB%E7%BB%9F%E6%8C%82%E6%AD%BB%22%5D%0A%20%20W%20--%3E%7C%22%E8%8E%B7%E5%8F%96%E6%97%B6%E5%B7%B2%20spin_lock_irqsave%22%7C%20OK%5B%22IRQ%20%E8%A2%AB%E5%B1%8F%E8%94%BD%EF%BC%8CA%20%E8%B7%91%E5%AE%8C%E4%B8%B4%E7%95%8C%E5%8C%BA%3Cbr%2F%3EISR%20%E8%BF%94%E5%9B%9E%E5%90%8E%E5%86%8D%E6%8B%BF%E9%94%81%22%5D%0A%20%20T2%5B%22%E5%A4%9A%E6%A0%B8%E5%9C%BA%E6%99%AF%3A%20%E4%BB%96%E6%A0%B8%20ISR%20%E6%83%B3%E6%8B%BF%E9%94%81%22%5D%20--%3E%20OK2%5B%22%E6%9C%AC%E5%9C%B0%E5%85%B3%20IRQ%20%E6%8C%A1%E4%B8%8D%E4%BD%8F%E4%BB%96%E6%A0%B8%3Cbr%2F%3E%E5%8F%AA%E8%83%BD%E9%9D%A0%20A%20%E5%B0%BD%E5%BF%AB%E9%87%8A%E6%94%BE%20%2B%20%E8%87%AA%E6%97%8B%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p><span class="marginnote">数字实例：TAS 乒乓的代价在 cache 行——4 个核各自旋读同一锁字，持有者每写一次 0，其他核的 cache 行全部失效、重新拉取；一次跨核往返常按几十到上百周期算，核越多烧得越快，这正是 MCS 排队要省的钱。</span></p><p><span class="marginnote">常见误区：初学者容易以为自旋锁和互斥量随便换着用。实际上分界在临界区时长——几纳秒到微秒级、不睡眠，用自旋（省两次上下文切换）；可能睡、耗时几十微秒以上，用睡眠锁，否则等待者把 CPU 烧成暖气。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>raw_spinlock</code> 与 RT 里改睡眠的路径写完。用户态自旋在锁持有者被切走时会空转整个量子，一般要 futex。也不把读写锁提前展开。</p><p>后课默认：IRQ 与极短内核路径用自旋。多核排队减少乒乓，下一课 MCS 锁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自旋：忙等、禁睡、关抢占；与 IRQ 共享数据时还要关本地中断。</li><li>临界区必须短；简单 TAS 会乒乓。</li><li>排队自旋是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',7))])}const T=l(p,[["render",c]]);export{u as __pageData,T as default};
